import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type DayReelProps = Record<string, any>;

const DayReel: React.FC<DayReelProps> = ({
  backgroundColor = "#0a0a0c",
  transparentBackground = false,
  durationInSeconds = 10,
  textColor = "#f4f4f5",
  accentColor = "#ef4444",
  startDay = 1,
  endDay = 30,
  prefixText = "DAY ",
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Anton"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const numDays = Math.max(1, endDay - startDay + 1);
  const totalFrames = durationInSeconds * fps;
  
  // Allocate 1.5 seconds for the fast rewind, the rest for the forward snapping
  const rewindFrames = 1.5 * fps;
  const forwardFrames = Math.max(fps, totalFrames - rewindFrames);

  // --- FORWARD PHASE LOGIC (Snapping Slot Machine) ---
  const dayFloatProgress = interpolate(frame, [0, forwardFrames], [0, 1], { 
    extrapolateRight: "clamp" 
  });
  const dayFloat = dayFloatProgress * (numDays - 1);
  
  const currentInt = Math.floor(dayFloat);
  const fraction = dayFloat - currentInt;

  // Hold on integer for 60% of the duration, snap to next in 40%
  const holdRatio = 0.6;
  let jumpFraction = 0;
  
  if (fraction > holdRatio) {
    jumpFraction = (fraction - holdRatio) / (1 - holdRatio);
    jumpFraction = Easing.bezier(0.25, 1, 0.5, 1)(jumpFraction); // Snappy spring-like curve
  }

  const forwardIndex = currentInt + jumpFraction;

  // --- REWIND PHASE LOGIC (Fast Continuous Spin) ---
  const isRewind = frame >= forwardFrames;
  const rewindFrame = Math.max(0, frame - forwardFrames);
  
  const rewindProgress = interpolate(rewindFrame, [0, rewindFrames], [0, 1], { 
    easing: Easing.inOut(Easing.cubic), 
    extrapolateRight: "clamp" 
  });
  
  // Calculate backwards from max index to 0
  const maxIndex = numDays - 1;
  const rewindIndex = maxIndex - (rewindProgress * maxIndex);

  // --- FINAL ACTIVE INDEX ---
  const activeIndex = isRewind ? rewindIndex : forwardIndex;

  // Visual Metrics
  const minDimension = Math.min(width, height);
  const itemHeight = minDimension * 0.35;
  const fontSize = itemHeight * 0.7;

  // Data Array
  const daysData = React.useMemo(() => {
    return Array.from({ length: numDays }).map((_, i) => ({
      index: i,
      text: `${prefixText}${startDay + i}`
    }));
  }, [numDays, startDay, prefixText]);

  // Viewport setup
  const wrapperStyle: React.CSSProperties = {
    position: "absolute",
    top: "50%",
    left: "50%",
    width: "100%",
    height: "100%",
    transform: "translate(-50%, -50%)",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    transformStyle: "preserve-3d",
    perspective: "1200px"
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Anton", overflow: "hidden" }}>
      
      {/* Background Gradient to draw focus to center */}
      <div style={{
        position: "absolute",
        width: "100%",
        height: "100%",
        background: `radial-gradient(circle at center, transparent 0%, ${backgroundColor} 80%)`,
        zIndex: 5,
        pointerEvents: "none"
      }} />

      {/* Target Highlight Track */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: "5%",
        right: "5%",
        height: `${itemHeight * 1.05}px`,
        transform: "translateY(-50%)",
        borderTop: `4px solid ${accentColor}`,
        borderBottom: `4px solid ${accentColor}`,
        background: `linear-gradient(90deg, transparent 0%, ${accentColor}10 50%, transparent 100%)`,
        zIndex: 2,
        pointerEvents: "none",
        opacity: 0.8
      }} />

      <div style={wrapperStyle}>
        {daysData.map((day) => {
          const distance = day.index - activeIndex;
          
          // Cull items far outside the view to keep performance high
          if (Math.abs(distance) > 5) return null;

          const absDist = Math.abs(distance);
          
          // Cylinder Projection Math
          const translateY = distance * itemHeight;
          const translateZ = absDist * -150; 
          const rotateX = distance * -30; // Tilt away from center
          
          const opacity = interpolate(absDist, [0, 1.5, 3], [1, 0.4, 0], { 
            extrapolateRight: "clamp" 
          });

          // Add a motion blur simulation via stretch during the fast rewind
          const scaleY = isRewind ? interpolate(rewindProgress, [0, 0.5, 1], [1, 1.4, 1]) : 1;

          return (
            <div key={day.index} style={{
              position: "absolute",
              fontSize: `${fontSize}px`,
              color: textColor,
              fontWeight: 400, // Anton is naturally heavy
              letterSpacing: "0.02em",
              textAlign: "center",
              width: "100%",
              opacity: opacity,
              transform: `translateY(${translateY}px) translateZ(${translateZ}px) rotateX(${rotateX}deg) scaleY(${scaleY})`,
              whiteSpace: "pre",
              textShadow: `0px 10px 30px rgba(0,0,0,0.8)`,
              transition: "none",
              zIndex: Math.round(10 - absDist),
            }}>
              {day.text}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default DayReel;